-- 2. The awakening's own recipes (refine_proto); nothing names them any more.
DELETE FROM world.refine_proto WHERE id IN (7100, 7101, 7102, 7103, 7104, 7105, 7106, 7107, 7108, 7110);

-- 3. The awakened pieces (bags, equipment, storage, offline shops - every window of player.item - and
--    the awards not yet taken) become the official level-87 weapon of the same kind at the same plus;
--    bonuses, stones and sockets stay on the piece.
UPDATE player.item SET vnum = vnum - 210 + 460 WHERE vnum BETWEEN 210 AND 219;
UPDATE player.item_award SET vnum = vnum - 210 + 460 WHERE vnum BETWEEN 210 AND 219;
UPDATE player.item SET vnum = vnum - 220 + 470 WHERE vnum BETWEEN 220 AND 229;
UPDATE player.item_award SET vnum = vnum - 220 + 470 WHERE vnum BETWEEN 220 AND 229;
UPDATE player.item SET vnum = vnum - 1160 + 1340 WHERE vnum BETWEEN 1160 AND 1169;
UPDATE player.item_award SET vnum = vnum - 1160 + 1340 WHERE vnum BETWEEN 1160 AND 1169;
UPDATE player.item SET vnum = vnum - 2190 + 2370 WHERE vnum BETWEEN 2190 AND 2199;
UPDATE player.item_award SET vnum = vnum - 2190 + 2370 WHERE vnum BETWEEN 2190 AND 2199;
UPDATE player.item SET vnum = vnum - 3170 + 3190 WHERE vnum BETWEEN 3170 AND 3179;
UPDATE player.item_award SET vnum = vnum - 3170 + 3190 WHERE vnum BETWEEN 3170 AND 3179;
UPDATE player.item SET vnum = vnum - 5150 + 5340 WHERE vnum BETWEEN 5150 AND 5159;
UPDATE player.item_award SET vnum = vnum - 5150 + 5340 WHERE vnum BETWEEN 5150 AND 5159;
UPDATE player.item SET vnum = vnum - 7170 + 7370 WHERE vnum BETWEEN 7170 AND 7179;
UPDATE player.item_award SET vnum = vnum - 7170 + 7370 WHERE vnum BETWEEN 7170 AND 7179;
